DROP TABLE IF EXISTS `sync_conflict`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sync_conflict` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `device_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `folder_id` bigint unsigned DEFAULT NULL,
  `file_id` bigint unsigned DEFAULT NULL,
  `relative_path` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `server_hash` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `local_hash` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `base_hash` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `server_version` bigint unsigned NOT NULL DEFAULT '0',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  `resolution` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `resolved_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sync_conflict_user_id` (`user_id`),
  KEY `idx_sync_conflict_device_id` (`device_id`),
  KEY `idx_sync_conflict_folder_id` (`folder_id`),
  KEY `idx_sync_conflict_file_id` (`file_id`),
  KEY `idx_sync_conflict_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
